import base64
import os
from pathlib import Path
from typing import List, Optional, Union


def extract_text_and_layout(image_input: Union[str, bytes, Path]) -> dict:
    """
    Extract plain text and layout information from a scanned document image using
    Azure AI Document Intelligence.

    Returns a dictionary with:
      - text: concatenated plain text
      - pages: page-level text and dimensions
      - paragraphs: paragraph text with bounding regions when available
      - tables: table cell contents and positions when available
    """
    from azure.core.credentials import AzureKeyCredential
    from azure.ai.documentintelligence import DocumentIntelligenceClient

    endpoint = os.environ["AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT"]
    key = os.environ["AZURE_DOCUMENT_INTELLIGENCE_KEY"]

    if isinstance(image_input, Path):
        data = image_input.read_bytes()
    elif isinstance(image_input, bytes):
        data = image_input
    else:
        path = Path(str(image_input))
        if path.exists():
            data = path.read_bytes()
        else:
            with open(str(image_input), "rb") as f:
                data = f.read()

    client = DocumentIntelligenceClient(endpoint=endpoint, credential=AzureKeyCredential(key))

    poller = client.begin_analyze_document(
        model_id="prebuilt-layout",
        analyze_request=data,
        content_type="image/png",
    )
    result = poller.result()

    full_text = result.content or ""

    pages = []
    for page in getattr(result, "pages", []) or []:
        page_lines = []
        for line in getattr(page, "lines", []) or []:
            page_lines.append(line.content)
        pages.append(
            {
                "page_number": getattr(page, "page_number", None),
                "width": getattr(page, "width", None),
                "height": getattr(page, "height", None),
                "unit": getattr(page, "unit", None),
                "text": "\n".join(page_lines).strip(),
            }
        )

    paragraphs = []
    for para in getattr(result, "paragraphs", []) or []:
        bounding_regions = []
        for br in getattr(para, "bounding_regions", []) or []:
            bounding_regions.append(
                {
                    "page_number": getattr(br, "page_number", None),
                    "polygon": getattr(br, "polygon", None),
                }
            )
        paragraphs.append(
            {
                "content": getattr(para, "content", None),
                "role": getattr(para, "role", None),
                "bounding_regions": bounding_regions,
            }
        )

    tables = []
    for table in getattr(result, "tables", []) or []:
        cells = []
        for cell in getattr(table, "cells", []) or []:
            cells.append(
                {
                    "row_index": getattr(cell, "row_index", None),
                    "column_index": getattr(cell, "column_index", None),
                    "content": getattr(cell, "content", None),
                    "row_span": getattr(cell, "row_span", None),
                    "column_span": getattr(cell, "column_span", None),
                }
            )
        tables.append(
            {
                "row_count": getattr(table, "row_count", None),
                "column_count": getattr(table, "column_count", None),
                "cells": cells,
            }
        )

    return {
        "text": full_text.strip(),
        "pages": pages,
        "paragraphs": paragraphs,
        "tables": tables,
    }
